// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address fuzzedCaller, address fuzzedRecipient) public {
        vm.assume(fuzzedCaller != address(0));
        vm.assume(fuzzedRecipient != address(0));
        vm.assume(fuzzedCaller != fuzzedRecipient);
        vm.assume(fuzzedCaller != address(c));
        vm.assume(fuzzedRecipient != address(c));

        uint256 bal = 1 ether;
        vm.deal(address(c), bal);

        bool ok = false;
        vm.prank(fuzzedCaller);
        try c.withdrawAll(fuzzedRecipient) { ok = true; } catch { ok = false; }

        assertTrue(!ok || fuzzedCaller == c.owner());
    }
}
